/**
 * 钱包解锁
 */
cc.Class({
    extends: cc.Component,

    properties: {
        _playUnlockState:0, 
    },

    onLoad () {
        Global.registerEvent(cc.vv.gameData._EventId.SLOT_TOTALBET_UPDATED,this.onChangeBetValue,this)
        let randomdata = cc.vv.gameData.getRandomData();
        this.UNLOCKVAL = randomdata.min;
        this.updateMoneyBag();

        Global.btnClickEvent(cc.find("btn", this.node), this.clickLockBtn, this);
    },

    start(){
        //处理符号接缝
        //this.setSymbolSpframe();
    },

    //设置
    setSymbolSpframe(){
        //let symbol = cc.vv.gameData.GetAtlasByName('symbol');
        //  symbol.getSpriteFrame("theme116_s_31").getTexture().setAntiAliasTexParameters();
        //  symbol.getSpriteFrame("theme116_s_32").getTexture().setAntiAliasTexParameters();
        //  symbol.getSpriteFrame("theme116_s_41").getTexture().setAntiAliasTexParameters();
        //  symbol.getSpriteFrame("theme116_s_42").getTexture().setAntiAliasTexParameters();
        //  symbol.getSpriteFrame("theme116_s_51").getTexture().setAntiAliasTexParameters();
        //  symbol.getSpriteFrame("theme116_s_52").getTexture().setAntiAliasTexParameters();
        //symbol.getSpriteFrame("theme116_s_31").getTexture().setFilters(cc.Texture2D.Filter.LINEAR, cc.Texture2D.Filter.LINEAR);
        //symbol.getSpriteFrame("theme116_s_32").getTexture().setFilters(cc.Texture2D.Filter.LINEAR, cc.Texture2D.Filter.LINEAR);
        //setAntiAliasTexParameters
    },

    //锁定/解锁钱包
    updateMoneyBag(){
        let betIdx = cc.vv.gameData.GetBetIdx()
        if(betIdx >= this.UNLOCKVAL){
            //解锁
            if(this._playUnlockState != 1){
                this._playUnlockState = 1
                Global.SlotsSoundMgr.playEffect('unlock');
                this.playUnlockAni('animation2',()=>{
                    
                });
            }
        }
        else{
            //锁定
            if(this._playUnlockState != 2){
                this._playUnlockState = 2
                Global.SlotsSoundMgr.playEffect('lock');
                this.playUnlockAni('animation1',()=>{

                });
            }
        }
    },

    //强制控制解锁状态
    setMoneybagLock(lock){
        if(lock){
            this._playUnlockState = 2
            this.playUnlockAni('animation1',()=>{

            });
        }else{
            this._playUnlockState = 1
            this.playUnlockAni('animation2',()=>{
                
            });
        }
    },

    //播放钱包锁定解锁动画
    playUnlockAni(aniname,callback){
        for(let i=1;i<7;i++){
            let suonode = cc.find(cc.js.formatStr('bag%s/suo',i),this.node);
            cc.vv.gameData.playSpine(suonode,aniname,false,callback);
        }
    },

    //押注额改变val
    onChangeBetValue(data){
       this.updateMoneyBag();
    },

    // 点击解锁
    clickLockBtn(){
        if (!cc.vv.gameData.GetBottomScript().GetSpinBtnState()) return;
        if (cc.vv.gameData.GetAutoModelTime() > 0) return;
        if (cc.vv.gameData.isFreeGame()) return;

        let betIdx = cc.vv.gameData.GetBetIdx();
        let betList = cc.vv.gameData.GetBetMults();
        if(this.UNLOCKVAL > betList.length){
            return;
        }

        if(betIdx < this.UNLOCKVAL){
            cc.vv.gameData.GetBottomScript().SetBetIdx(this.UNLOCKVAL)
        }
    },
});
