
cc.Class({
    extends: require('LMSlots_Reel_Base'),

    properties: {

    },
    onLoad () {
       this._super();
       this._isAntiReel = false;
    },

    //隐藏时重置位置
    resetReelPos(){
        this._bStoping = true
        this._curY = 0
        this._holderNode.y = this._holderOrigPosY
    },

    //创建lock wild
    loadLockWild(){
        node.parent = this._holderNode
    },

    //重写显示加速效果
    ShowAntiEffect:function(bShow,name){
        this._super(bShow,name);
        if(!this._isAntiReel&&!bShow){
            return;
        }
        if(this._reelIdx<4&&!bShow){
            return;
        }
        this._isAntiReel = bShow;
        cc.vv.gameData.GetSlotsScript().showSpeedUpMask(bShow);
    },
});
