
cc.Class({
    extends: cc.Component,

    properties: {
        bgs: [cc.SpriteFrame],
    },

    onLoad(){
        this._pipeUI = cc.find('wheel_pipeui',this.node);
        this._randomWildsUI = cc.find('wheel_randomwildsui',this.node);
        this._caitlynUI = cc.find('wheel_caitlynui',this.node);
        this._horseShoeUI = cc.find('wheel_horseshoeui',this.node);
        this._leprechaunUI = cc.find('wheel_leprechaunui',this.node);
        this._moreshpinsUI = cc.find('wheel_morespinsui',this.node);
        this._moneyactiveUI = cc.find('wheel_moneyactive',this.node);
        this._collectFreeUI = cc.find('free_collectui',this.node);
        this._startFreeUI = cc.find('free_startui',this.node);

        this._transitionNode = cc.find('Canvas/safe_node/screenspine/transition');

        this._btnstart = cc.find('mask',this._startFreeUI)
        Global.btnClickEvent(this._btnstart,this.onFreeGameStart,this)

        this._btncollect = cc.find('node/btn_collect',this._collectFreeUI)
        Global.btnClickEvent(this._btncollect,this.onFreeGameCollect,this)
    },

    //显示转盘结果界面 
    async showWheelResultUI(wheeldata){
        if(wheeldata.idx==1){
            //GRAND
            await this.showWheelUI(this._leprechaunUI,wheeldata.result);
        }else if(wheeldata.idx == 2||wheeldata.idx == 5||wheeldata.idx == 8||wheeldata.idx == 11){
            //RANDOMWILD
            await this.showWheelUI(this._randomWildsUI,wheeldata.result);
        }else if(wheeldata.idx==3||wheeldata.idx==9){
            //EXTRASPINS 3 9 (解锁前为钱包)
            let showextra = cc.vv.gameData.isOpenWheelExtraSpins();
            if(showextra){
                await this.addExtraSpins(wheeldata.result.extraSpins);
            }else{
                await this.showWheelUI(this._moneyactiveUI,wheeldata.result);
            }
        }else if(wheeldata.idx == 6||wheeldata.idx == 12){
            await this.addExtraSpins(wheeldata.result.extraSpins);
        }else if(wheeldata.idx == 4){
            //major
            await this.showWheelUI(this._horseShoeUI,wheeldata.result);
        }else if(wheeldata.idx == 7){
            //minor
            await this.showWheelUI(this._caitlynUI,wheeldata.result);
        }else if(wheeldata.idx == 10){
            //mini
            await this.showWheelUI(this._pipeUI,wheeldata.result);
        }
    },

    //获得额外旋转次数
    async addExtraSpins(extraspins){
        let lbltimes = cc.find('node/spintimes',this._moreshpinsUI);
        lbltimes.getComponent(cc.Label).string = extraspins;
        await this.showWheelUI(this._moreshpinsUI);
    },

    //转盘结果界面显示
    async showWheelUI(uinode,wheelresult){
        return new Promise((success)=>{
            Global.SlotsSoundMgr.stopBgm();
            Global.SlotsSoundMgr.playEffect('normal_dialog_show2');
            uinode.active = true;
            let mainnode = cc.find('node',uinode);
            mainnode.scale = 0;
            cc.tween(mainnode).to(0.3,{scale:1},{easing:'backOut'}).delay(2).call(()=>{
                Global.SlotsSoundMgr.playEffect('normal_dialog_close');

                if(wheelresult&&wheelresult.respin){
                    cc.vv.gameData.GetSlotsScript().ShowBottomWin(wheelresult.winCoin,wheelresult.winCoin,false,()=>{
                        cc.tween(mainnode).to(0.3,{scale:0},{easing:'backIn'}).call(()=>{
                            uinode.active = false;
                            success();
                        }).start();
                    });
                }else{
                    cc.tween(mainnode).to(0.3,{scale:0},{easing:'backIn'}).call(()=>{
                        uinode.active = false;
                        success();
                    }).start();
                }
            }).start();
        })
    },

    //显示免费开始界面
    async showFreeStartUI(){
        return new Promise(async(success)=>{
            Global.SlotsSoundMgr.stopBgm();
            Global.SlotsSoundMgr.playEffect('normal_dialog_show1');
            this._nextStep = success;
            this._startFreeUI.active = true;
            let mainnode = cc.find('node',this._startFreeUI);
            let btnstart = cc.find('btn_start',mainnode);
            mainnode.scale = 0;
            cc.tween(mainnode).to(0.3,{scale:1},{easing:'backOut'}).start();
            var repeattime = cc.sequence(cc.repeat(cc.sequence(cc.scaleTo(0.5, 1.2), cc.scaleTo(0.5, 1)),2),cc.delayTime(1));
            btnstart.runAction(cc.repeatForever(repeattime));

            let totalfree = cc.vv.gameData.GetTotalFree();
            let wheeldata = cc.vv.gameData.getWheelData();
            if(wheeldata){
                totalfree+=wheeldata.result.extraSpins;
            }
            cc.find('node/lbl_awardtimes',this._startFreeUI).getComponent(cc.Label).string = totalfree;

            this._btnstart.getComponent(cc.Button).interactable = true;
            await cc.vv.gameData.awaitTime(0.5);
            cc.vv.gameData.checkAutoPlay(this._startFreeUI, this.onFreeGameStart.bind(this));
        })
    },

    //显示免费结束界面
    async showFreeOverUI(){
        return new Promise(async (success)=>{
            Global.SlotsSoundMgr.stopBgm();
            Global.SlotsSoundMgr.playEffect('normal_dialog_show3');
            this._nextStep = success;
            this._collectFreeUI.active = true;
            let mainnode = cc.find('node',this._collectFreeUI);
            mainnode.scale = 0;
            cc.tween(mainnode).to(0.3,{scale:1},{easing:'backOut'}).start();
    
            let lblreward = cc.find('node/rewardcoins',this._collectFreeUI);
            let nWin = cc.vv.gameData.GetGameTotalFreeWin();
            Global.doRoallNumEff(lblreward,0,nWin,1,null,null,0,true);

            this._btncollect.getComponent(cc.Button).interactable = true;
            await cc.vv.gameData.awaitTime(0.5);
            cc.vv.gameData.checkAutoPlay(this._collectFreeUI, this.onFreeGameCollect.bind(this));
        })
    },

    //点击免费游戏开始
    onFreeGameStart(){
        this._startFreeUI.stopAllActions();

        this._btnstart.getComponent(cc.Button).interactable = false;
        Global.SlotsSoundMgr.playEffect('normal_dialog_click');
        let mainnode = cc.find('node',this._startFreeUI);
        cc.tween(mainnode).to(0.3,{scale:0},{easing:'backIn'}).call(()=>{
            this._startFreeUI.active = false;
            this.playTransition(()=>{
                if(this._nextStep)this._nextStep();
                Global.SlotsSoundMgr.playBgm('free_bgm');
                cc.vv.gameData.GetBottomScript().CanDoNextRound();
            });
            this.scheduleOnce(() => {
                this.changeGameBackimage(true);
                let total = cc.vv.gameData.GetTotalFree();
                let wheeldata = cc.vv.gameData.getWheelData();
                if(wheeldata){
                    total+=wheeldata.result.extraSpins;
                }
                cc.vv.gameData.SetTotalFree(total);
                cc.vv.gameData.SetFreeTime(total);
                //转盘数据
                cc.vv.gameData.GetBottomScript().ShowFreeModel(true,0,total)
            }, 2);
        }).start();
    },

    //点击免费游戏收集
    onFreeGameCollect(){
        this._collectFreeUI.stopAllActions();
        this._btncollect.getComponent(cc.Button).interactable = false;
        Global.SlotsSoundMgr.playEffect('normal_dialog_close');

        let lblreward = cc.find('node/rewardcoins',this._collectFreeUI);
        let nWin = cc.vv.gameData.GetGameTotalFreeWin();
        lblreward.stopAllActions();
        let delayT = 0;
        if(Global.FormatCommaNumToNum(lblreward.getComponent(cc.Label).string) < nWin){
            lblreward.getComponent(cc.Label).string = Global.FormatNumToComma(nWin);
            delayT = 0.2;
        }

        let mainnode = cc.find('node',this._collectFreeUI);
        cc.tween(mainnode).delay(delayT).to(0.3,{scale:0},{easing:'backIn'}).call(()=>{
            Global.SlotsSoundMgr.stopBgm();
            this._collectFreeUI.active = false;
            this.playTransition(()=>{
                // cc.vv.gameData.GetSlotsScript().resumeCardsState();
                let freewin = cc.vv.gameData.GetGameTotalFreeWin();
                cc.vv.gameData.GetSlotsScript().ShowBottomWin(freewin,freewin,true,()=>{
                    if(this._nextStep)this._nextStep();
                });
            });
            this.scheduleOnce(() => {
                this.changeGameBackimage(false);
                if(!cc.vv.gameData.isOpenWheelExtraSpins()){
                    cc.vv.gameData.GetSlotsScript().lockMoneyBag(true);
                }
                cc.vv.gameData.GetBottomScript().ShowFreeModel(false)
                cc.vv.gameData.GetSlotsScript().resumeCardsState();
            }, 2);
        }).start();
    },

    //播放过场动画
    playTransition(callback){
        Global.SlotsSoundMgr.playEffect('transition');
        cc.vv.gameData.playSpine(this._transitionNode,'animation',false,callback);
    },

    //切换游戏背景
    changeGameBackimage(isfree){
        cc.find("Canvas/safe_node/bg").active = !isfree;
        cc.find("Canvas/safe_node/free_bg").active = isfree;

        /*let bg = cc.find("Canvas/safe_node/bg").getComponent(cc.Sprite);
        if(isfree){
            bg.spriteFrame = this.bgs[1];
        }else{
            bg.spriteFrame = this.bgs[0];
        }*/
    },
});
