
cc.Class({
    extends: require('LMSlots_Symbol_Base'),

    properties: {
       
    },

    //重写赢钱动画(不需要播动画)
    playWinAnimation(){
       
    },

    //重写开始旋转时刻
    StartMove:function(){
        this.setAnimationToTop(false)
        this.ShowKuang(false)
        //this.stopWinTweenAction()
        this.node.zIndex = 50 - this._symbolIdx  + this._reelIdx*10;
    },

    //播放进入免费动画
    playScatterAnimation(isplay){
        let aninodename = '';
        if((this._id == 5||this._id == 6||this._id == 7)&&this._symbolIdx == 0){
            aninodename = 'leprechaun1';
        }
        if(this._id == 501||this._id == 601||this._id == 701){
            aninodename = 'leprechaun2';
        }
        if(aninodename == '')
            return;
        if(this._showNode)this._showNode.active = false;
        this._showNode = cc.find(aninodename,this.node);
        if(isplay){
            this._showNode.active = true;
            let aniname = this.getAnimationName();
            this._showNode.getComponent(sp.Skeleton).setAnimation(0,aniname,true);
        }else{
            this._showNode.active = false;
        }
    },

    //获取动作名
    getAnimationName(){
        switch (this._id) {
            case 5:
            case 501:
                return 'animation3';
            case 6:
            case 601:
                return 'animation2';
            case 7:
            case 701:
                return 'animation1';
        }
        return 'animation1'
    },

    //设置符号蒙版状态
    setSymbolMask(ismask){
        let children = this.node.children;
        for (let i = 0; i < children.length; i++) {
            let name = children[i].name;
            if(name != 'leprechaun1'&&name!='leprechaun2'&&name!='s31'&&name!='s32'&&
            name!='s41'&&name!='s42'&&name!='s51'&&name!='s52'&&name!='null'){
                if(ismask){
                    children[i].color = cc.color(127,127,127);
                }else{
                    children[i].color = cc.color(255,255,255);
                }
            }
        }
    }
});
