
cc.Class({
    extends: cc.Component,

    properties: {
        
    },

    onLoad(){
        this._mainNode = cc.find('mainnode',this.node);
        this._rorationWheel = cc.find("node_wheel/wheelNode/rotationWheel", this._mainNode);
        this._startBtnNode = cc.find('node_wheel/wheelNode/btn_spin',this._mainNode);
        Global.btnClickEvent(this._startBtnNode,this.onWheelStart,this)
    },

    onEnable(){
        cc.vv.NetManager.registerMsg(MsgId.SLOT_SUBGAME_DATA, this.onRcvSubGameAction, this);
    },

    onDisable(){
        cc.vv.NetManager.unregisterMsg(MsgId.SLOT_SUBGAME_DATA, this.onRcvSubGameAction, false, this); 
    },

    //接收51消息返回
    onRcvSubGameAction:function(msg){
        if(msg.code == 200){
            this._wheelData = msg.data;
            cc.vv.gameData.SetWheelData(msg.data);
            this.showResult(msg.data.idx);
        }
    },

    //发送进入免费游戏
    sendEnterFreeeGame(){
        let req = {c: MsgId.SLOT_SUBGAME_DATA};
        req.data = {}
        req.data.rtype = 1
        req.gameid = cc.vv.gameData.getGameId()
        cc.vv.NetManager.send(req,true);
    },

    //转盘开始旋转
    onWheelStart(btn){
        this._startBtnNode.stopAllActions();
        Global.SlotsSoundMgr.playEffect('wheel_click');
        this._startBtnNode.getComponent(cc.Button).interactable = false;
        cc.vv.gameData.playSpine(this._startBtnNode,'animation3',false,()=>{
            //发送开始旋转
            this.sendEnterFreeeGame();
        });
    },

    //显示游戏结果(开始旋转)
    async showResult(resultidx){
        let offsetangle = this._rorationWheel.angle;
        if(this._targetIdx!=-1){
            //第二次旋转需要多加18度
            offsetangle = this._rorationWheel.angle%360-this._targetIdx*30;
        }
        this._targetIdx = resultidx - 1;
        let diffAngle = this._targetIdx*30;
        let targetAngle = -diffAngle + offsetangle;
        let mRound = 13; //转动圈数
        // await this.awaitTime(1);
        Global.SlotsSoundMgr.playEffect('wheel_spin');
        await this.playActions(this._rorationWheel, [
            cc.rotateTo(0.5*mRound, 360*mRound + targetAngle).easing(cc.easeSineInOut()),
        ]);
        //播放中奖效果
        if(this._wheelData.result.respin){
            Global.SlotsSoundMgr.playEffect('wheel_stop2');
        }else{
            Global.SlotsSoundMgr.playEffect('wheel_stop1');
        }
        
        this.playWheelReward(true);
        await this.awaitTime(2);
        //显示结算界面
        await this.showResultUI();
        if(this._wheelData.result.unLockRandomGame){
            //解锁钱袋
            cc.vv.gameData.GetSlotsScript().lockMoneyBag(false);
        }
    },

    playActions (node, actionsArr) {
        return new Promise((success)=>{
            actionsArr.push(cc.callFunc(()=>{
                success();
            }));

            node.active = true;
            node.runAction(cc.sequence(actionsArr));
        });
    },
    
    //播放/停止获取奖励特效
    playWheelReward(isplay){
        let getreward = cc.find('node_wheel/wheelNode/getreward',this._mainNode);
        if(isplay){
            cc.vv.gameData.playSpine(getreward,'animation',true,null);
        }else{
            getreward.active = false;
        }
    },

    //显示转盘结果界面
    async showResultUI(){
        await cc.vv.gameData.getUIMgr().showWheelResultUI(this._wheelData);
        await this.awaitTime(1);
        await this.exitWheelGame();
    },

    //控制钱袋和extra spins的显示(true 显示extra spins)
    showExtraspins(showextraspins){
        cc.find('randsymbol1',this._rorationWheel).active = showextraspins;
        cc.find('randsymbol2',this._rorationWheel).active = showextraspins;
        cc.find('randsymbol3',this._rorationWheel).active = !showextraspins;
        cc.find('randsymbol4',this._rorationWheel).active = !showextraspins;
    },

    //进入转盘游戏
    enterWheelGame(success){
        Global.SlotsSoundMgr.playBgm('bonus_bgm');
        this._nextStep = success;
        this._targetIdx = -1;
        //动态显示钱袋和extra spins
        let showextra = cc.vv.gameData.isOpenWheelExtraSpins();
        this.showExtraspins(showextra);
        this._rorationWheel.angle = 0;
        this._mainNode.active = true;
        this._startBtnNode.getComponent(cc.Button).interactable = true;
        let wheelnode = cc.find('node_wheel',this._mainNode);
        Global.SlotsSoundMgr.playEffect('wheel_out');
        cc.tween(wheelnode).to(0.3,{position:cc.v2(0,25)}).call(()=>{
            cc.vv.gameData.playSpine(this._startBtnNode,'animation1',false,()=>{
                cc.vv.gameData.playSpine(this._startBtnNode,'animation2',true,null);
            });
            cc.vv.gameData.checkAutoPlay(this._startBtnNode, this.onWheelStart.bind(this));
        }).start();
    },

    //退出转盘游戏
    exitWheelGame(){
        this.playWheelReward(false);
        if(this._wheelData.result.respin){
            //如果需要再转一次
            Global.SlotsSoundMgr.playEffect('spin_out');
            this._startBtnNode.getComponent(cc.Button).interactable = true;
            //let wheelnode = cc.find('node_wheel',this._mainNode);
            cc.vv.gameData.playSpine(this._startBtnNode,'animation1',false,()=>{
                cc.vv.gameData.playSpine(this._startBtnNode,'animation2',true,null);
            });
            cc.vv.gameData.checkAutoPlay(this._startBtnNode, this.onWheelStart.bind(this));
            return;
        }
        let wheelnode = cc.find('node_wheel',this._mainNode);
        cc.tween(wheelnode).to(0.3,{position:cc.v2(0,-1000)}).call(()=>{
            this._mainNode.active = false;
            this.scheduleOnce(() => {
                if(this._nextStep){
                    this._nextStep();
                }else{
                    cc.vv.gameData.GetSlotsScript().reconnectFreeGame();
                }
            }, 1);
        }).start();
    },

    awaitTime (time) {
        return new Promise((success)=>{
            this.scheduleOnce(()=>{
                success()
            },time);
        });
    },
});
