
cc.Class({
    extends: require('LMSlots_GameData_Base'),

    properties: {
        
    },

    //重写deskInfo进入游戏获得的服务端数据
    init(deskInfo,gameId,gameJackpot){
        this._selectData = deskInfo.select;
        this._randomGame = deskInfo.randomGame;
        this._freeGameData = deskInfo.freeGameData;
        this._super(deskInfo,gameId,gameJackpot);
     },

     //重写接收旋转消息
     OnRcvNetSpine:function(msg){
        //msg = {"allFreeCnt":5,"c":44,"subGameInfo":{"isMustJoin":-1,"subGamid":-1},"betcoin":20000,"freeResult":{"freeInfo":[],"triFreeCnt":1},"spEffect":{"wincoin":26000,"kind":0},"resultCards":[18,1,14,17,17,6,18,1,14,14,17,1,10,16,16,14,11,1,9,10,16,18,11,8,12,6,16,18,11,8,12,6,15,15,15,5],"freeGameData":{"stickWild3Idxs":[3,9,24,30],"randomWildIdxs":[20,18,13,24,36,3,26,22,32]},"lastBetCoin":1461100,"code":200,"coin":1461100,"pooljp":0,"select":{"state":false},"spcode":200,"randomGame":{"min":3,"cols":[]},"nextBetLine":{"spcode":500},"scatterZJLuXian":{"mult":0,"coin":0,"indexs":[]},"spLuXian":0,"freeCnt":3,"zjLuXian":[{"mult":1,"coin":1000,"xlid":1,"card":18,"indexs":[1,2,3]},{"mult":1,"coin":1000,"xlid":2,"card":18,"indexs":[7,8,9]},{"mult":1,"coin":1000,"xlid":3,"card":16,"indexs":[13,14,15]},{"mult":1,"coin":1000,"xlid":7,"card":18,"indexs":[7,8,9]},{"mult":1,"coin":1000,"xlid":8,"card":16,"indexs":[13,14,15]},{"mult":1,"coin":1000,"xlid":12,"card":18,"indexs":[7,8,9]},{"mult":1,"coin":1000,"xlid":13,"card":16,"indexs":[13,14,15]},{"mult":1,"coin":1000,"xlid":16,"card":18,"indexs":[1,2,3]},{"mult":1,"coin":1000,"xlid":17,"card":18,"indexs":[7,8,9]},{"mult":1,"coin":1000,"xlid":18,"card":16,"indexs":[13,14,15]},{"mult":1,"coin":1000,"xlid":21,"card":18,"indexs":[7,8,9]},{"mult":1,"coin":1000,"xlid":22,"card":16,"indexs":[13,14,15]},{"mult":1,"coin":1000,"xlid":25,"card":18,"indexs":[1,2,3]},{"mult":1,"coin":1000,"xlid":27,"card":18,"indexs":[1,2,3]},{"mult":1,"coin":1000,"xlid":28,"card":18,"indexs":[7,8,9]},{"mult":1,"coin":2000,"xlid":29,"card":16,"indexs":[13,14,15,22]},{"mult":1,"coin":1000,"xlid":32,"card":18,"indexs":[7,8,9]},{"mult":1,"coin":1000,"xlid":33,"card":16,"indexs":[13,14,15]},{"mult":1,"coin":1000,"xlid":37,"card":18,"indexs":[1,2,3]},{"mult":1,"coin":1000,"xlid":38,"card":18,"indexs":[7,8,9]},{"mult":1,"coin":2000,"xlid":39,"card":16,"indexs":[13,14,15,22]},{"mult":1,"coin":1000,"xlid":42,"card":18,"indexs":[7,8,9]},{"mult":1,"coin":1000,"xlid":43,"card":16,"indexs":[13,14,15]},{"mult":1,"coin":1000,"xlid":48,"card":16,"indexs":[13,14,21]}],"mults":[10000,20000,50000,100000,150000,200000],"freeWinCoin":66000,"wincoin":26000,"addMult":1}
        if(msg.code == 200){
            this._selectData = msg.select; 
            this._randomGame = msg.randomGame;
            this._freeGameData = msg.freeGameData;
            this._super(msg);
        }
    },

    //如果押注额大于等于randomGame.min 解锁转盘变为extra spins
    isOpenWheelExtraSpins: function () {
        if(this._randomGame){
            return this.GetBetIdx() >= this._randomGame.min;
        }
        return false;
    },

    //获取select数据
    getSelectData:function(){
        return this._selectData;
    },

    //获取randomdata
    getRandomData(){
        return this._randomGame;
    },

    //获取freegame数据
    getFreeGameData(){
        return this._freeGameData;
    },

    //设置ui管理脚本
    setUIMgrScript(uimgr){
        this._uiMgr = uimgr;
    },

    //获取ui管理脚本
    getUIMgr(){
        return this._uiMgr;
    },

    setFreeGameScript(freescript){
        this._freeGameScript = freescript;
    },

    getFreeGame(){
        return this._freeGameScript;
    },

    //转盘数据
    SetWheelData(wheeldata){
        this._wheelData = wheeldata;
    },

    getWheelData(){
        return this._wheelData;
    },

    //清除wheeldata
    clearWheelData(){
        this._wheelData = null;
    },

    //是否触发普通免费 
    isTriggerNormalFree: function(){
        return (this._gameInfo.allFreeCnt>0&&this._gameInfo.allFreeCnt==this._gameInfo.freeCnt);
    },

    //是否免费结束
    isNormalFreeOver:function(){
        if(this._gameInfo.allFreeCnt>0&&this._gameInfo.freeCnt==0)
            return true;
        return false;
    },

    // 是否处于免费游戏中
    setIsFreeGame(val){
        this._isFreeGame = val;
    },
    isFreeGame(){
        return this._isFreeGame;
    },

    //按节点播放spine
    playSpine:function(node,aniName,loop,endCall){
        if(node){
            node.active = true
            let ske = node.getComponent(sp.Skeleton)
            if(ske){
                ske.setAnimation(0,aniName,loop)
                ske.setCompleteListener(() => {
                    if(endCall){
                        endCall()
                    }
                })
            }
        }
    },
});
