
cc.Class({
    extends: require('LMSlots_Logic_Base'),

    properties: {
        
    },

    onLoad(){
        //免费游戏脚本
        let script_freegame = this.node.addComponent('ElvesBlessing_FreeGame');
        cc.vv.gameData.setFreeGameScript(script_freegame);

        //ui管理
        let uinode = cc.find('safe_node/gameUI',this.node)
        let script_uimgr = uinode.getComponent('ElvesBlessing_UIMgr');
        cc.vv.gameData.setUIMgrScript(script_uimgr)

        this._super();
    },
});
